#!/usr/bin/env python3
from pathlib import Path
import sys

if len(sys.argv) != 2:
    raise SystemExit("usage: patch_global_flash.py PATH/TO/Plugin.cpp")

p = Path(sys.argv[1])
s = p.read_text(encoding="utf-8")

s = s.replace(
    "class JiantProcessor final : public juce::AudioProcessor\n",
    "class JiantProcessor final : public juce::AudioProcessor, private juce::Timer\n",
    1,
)

old_ctor_end = '''        for (auto& n : midiNotes)\n            n.store (0);\n    }\n\n    const juce::String getName() const override { return JucePlugin_Name; }\n'''
new_ctor_end = '''        for (auto& n : midiNotes)\n            n.store (0);\n\n        loadGlobalFlashFromDisk();\n        startTimer (500);\n    }\n\n    ~JiantProcessor() override\n    {\n        stopTimer();\n        persistGlobalFlashNow (true);\n    }\n\n    const juce::String getName() const override { return JucePlugin_Name; }\n'''
if old_ctor_end not in s:
    raise SystemExit("processor constructor block changed")
s = s.replace(old_ctor_end, new_ctor_end, 1)

old_state = '''    void getStateInformation (juce::MemoryBlock& destData) override\n    {\n        juce::MemoryOutputStream out (destData, false);\n        out.writeInt (0x4A49414E); // JIAN\n        out.writeInt (1);\n        for (const auto& v : knobUi)\n            out.writeFloat (v.load());\n\n        const juce::ScopedLock lock (gCoreLock);\n        if (gCoreBooted)\n        {\n            const uint32_t bytes = web_nor_size();\n            out.writeInt (static_cast<int> (bytes));\n            out.write (web_nor(), bytes);\n        }\n        else if (!pendingFlash.empty())\n        {\n            out.writeInt (static_cast<int> (pendingFlash.size()));\n            out.write (pendingFlash.data(), pendingFlash.size());\n        }\n        else\n        {\n            out.writeInt (0);\n        }\n    }\n\n    void setStateInformation (const void* data, int sizeInBytes) override\n    {\n        juce::MemoryInputStream in (data, static_cast<size_t> (sizeInBytes), false);\n        if (in.readInt() != 0x4A49414E)\n            return;\n        const int version = in.readInt();\n        if (version != 1)\n            return;\n\n        for (auto& v : knobUi)\n            v.store (juce::jlimit (0.0f, 1.0f, in.readFloat()));\n\n        const int bytes = in.readInt();\n        if (bytes <= 0 || bytes > 2 * 1024 * 1024 || in.getNumBytesRemaining() < bytes)\n            return;\n\n        std::vector<uint8_t> restored (static_cast<size_t> (bytes));\n        in.read (restored.data(), bytes);\n\n        const juce::ScopedLock lock (gCoreLock);\n        if (!gCoreBooted)\n        {\n            pendingFlash = std::move (restored);\n        }\n        else if (static_cast<uint32_t> (bytes) == web_nor_size())\n        {\n            std::memcpy (web_nor(), restored.data(), static_cast<size_t> (bytes));\n        }\n    }\n'''
new_state = '''    void getStateInformation (juce::MemoryBlock& destData) override\n    {\n        // Version 2 deliberately does not embed the emulated NOR flash in the DAW\n        // project. The flash is now shared globally, like the hardware's storage.\n        juce::MemoryOutputStream out (destData, false);\n        out.writeInt (0x4A49414E); // JIAN\n        out.writeInt (2);\n        for (const auto& v : knobUi)\n            out.writeFloat (v.load());\n    }\n\n    void setStateInformation (const void* data, int sizeInBytes) override\n    {\n        juce::MemoryInputStream in (data, static_cast<size_t> (sizeInBytes), false);\n        if (in.readInt() != 0x4A49414E)\n            return;\n        const int version = in.readInt();\n        if (version != 1 && version != 2)\n            return;\n\n        for (auto& v : knobUi)\n            v.store (juce::jlimit (0.0f, 1.0f, in.readFloat()));\n\n        // v2 uses only the global flash file. For v1 projects, import their old\n        // embedded flash only when no global bank exists yet. This migrates old\n        // projects without allowing them to overwrite a newer global bank.\n        if (version != 1 || globalFlashAuthoritative)\n            return;\n\n        const int bytes = in.readInt();\n        if (bytes <= 0 || bytes > 2 * 1024 * 1024 || in.getNumBytesRemaining() < bytes)\n            return;\n\n        std::vector<uint8_t> restored (static_cast<size_t> (bytes));\n        in.read (restored.data(), bytes);\n\n        const juce::ScopedLock lock (gCoreLock);\n        if (!gCoreBooted)\n        {\n            pendingProjectFlash = std::move (restored);\n        }\n        else if (static_cast<uint32_t> (bytes) == web_nor_size())\n        {\n            std::memcpy (web_nor(), restored.data(), static_cast<size_t> (bytes));\n            lastGlobalFlash.clear(); // force migration to disk on the next timer tick\n        }\n    }\n'''
if old_state not in s:
    raise SystemExit("state persistence block changed")
s = s.replace(old_state, new_state, 1)

old_boot = '''    void ensureCoreBootedLocked()\n    {\n        if (gCoreBooted)\n            return;\n\n        web_nor_erase();\n        if (!pendingFlash.empty() && pendingFlash.size() == web_nor_size())\n            std::memcpy (web_nor(), pendingFlash.data(), pendingFlash.size());\n        web_seed (0x4A49414Eu);\n        web_boot();\n        web_master (static_cast<uint32_t> (std::lround (knobUi[0].load() * 1023.0f)));\n        gCoreBooted = true;\n    }\n\n    void handleMidiLocked (const juce::MidiMessage& m)\n'''
new_boot = '''    void ensureCoreBootedLocked()\n    {\n        if (gCoreBooted)\n            return;\n\n        web_nor_erase();\n        const size_t bytes = static_cast<size_t> (web_nor_size());\n\n        if (pendingGlobalFlash.size() == bytes)\n        {\n            std::memcpy (web_nor(), pendingGlobalFlash.data(), bytes);\n            lastGlobalFlash = pendingGlobalFlash;\n        }\n        else if (pendingProjectFlash.size() == bytes)\n        {\n            // One-time migration path for projects saved by v1 of the plugin.\n            std::memcpy (web_nor(), pendingProjectFlash.data(), bytes);\n            lastGlobalFlash.clear();\n        }\n\n        pendingGlobalFlash.clear();\n        pendingProjectFlash.clear();\n        web_seed (0x4A49414Eu);\n        web_boot();\n        web_master (static_cast<uint32_t> (std::lround (knobUi[0].load() * 1023.0f)));\n        gCoreBooted = true;\n    }\n\n    void loadGlobalFlashFromDisk()\n    {\n        globalFlashFile = juce::File::getSpecialLocation (juce::File::userApplicationDataDirectory)\n                              .getChildFile ("JIANT FM")\n                              .getChildFile ("jiant_flash.bin");\n\n        juce::MemoryBlock data;\n        if (globalFlashFile.existsAsFile() && globalFlashFile.loadFileAsData (data)\n            && data.getSize() > 0 && data.getSize() <= 2u * 1024u * 1024u)\n        {\n            const auto* begin = static_cast<const uint8_t*> (data.getData());\n            pendingGlobalFlash.assign (begin, begin + data.getSize());\n            lastGlobalFlash = pendingGlobalFlash;\n            globalFlashAuthoritative = true;\n        }\n    }\n\n    void persistGlobalFlashNow (bool force)\n    {\n        std::vector<uint8_t> snapshot;\n        {\n            const juce::ScopedLock lock (gCoreLock);\n            if (!gCoreBooted)\n                return;\n\n            const size_t bytes = static_cast<size_t> (web_nor_size());\n            snapshot.resize (bytes);\n            std::memcpy (snapshot.data(), web_nor(), bytes);\n        }\n\n        if (!force && snapshot == lastGlobalFlash)\n            return;\n\n        const auto dir = globalFlashFile.getParentDirectory();\n        if (!dir.exists() && !dir.createDirectory())\n            return;\n\n        juce::TemporaryFile temp (globalFlashFile);\n        if (temp.getFile().replaceWithData (snapshot.data(), snapshot.size())\n            && temp.overwriteTargetFileWithTemporary())\n        {\n            lastGlobalFlash = std::move (snapshot);\n            globalFlashAuthoritative = true;\n        }\n    }\n\n    void timerCallback() override\n    {\n        // File I/O happens on JUCE's message thread, never on the audio thread.\n        // 500 ms keeps SAVE responsive while avoiding unnecessary disk writes.\n        persistGlobalFlashNow (false);\n    }\n\n    void handleMidiLocked (const juce::MidiMessage& m)\n'''
if old_boot not in s:
    raise SystemExit("core boot block changed")
s = s.replace(old_boot, new_boot, 1)

old_fields = '''    std::atomic<uint32_t> buttonMask { 0 };\n    std::atomic<uint32_t> physicalKeyMask { 0 };\n    std::vector<uint8_t> pendingFlash;\n\n    JUCE_DECLARE_NON_COPYABLE_WITH_LEAK_DETECTOR (JiantProcessor)\n'''
new_fields = '''    std::atomic<uint32_t> buttonMask { 0 };\n    std::atomic<uint32_t> physicalKeyMask { 0 };\n    std::vector<uint8_t> pendingProjectFlash;\n    std::vector<uint8_t> pendingGlobalFlash;\n    std::vector<uint8_t> lastGlobalFlash;\n    juce::File globalFlashFile;\n    bool globalFlashAuthoritative = false;\n\n    JUCE_DECLARE_NON_COPYABLE_WITH_LEAK_DETECTOR (JiantProcessor)\n'''
if old_fields not in s:
    raise SystemExit("processor field block changed")
s = s.replace(old_fields, new_fields, 1)

p.write_text(s, encoding="utf-8")
print(f"patched global cross-project flash persistence in {p}")
